4		"strings"
5		"testing"
6	)
7	
8	// 本文件为“登记课程要求时按用户给出的完整编号确定学生与课程”这项行为
9	// 提供回归保障。记录文件可以合法保存带前后空白的学生编号、课程编号与
10	// 要求编号，Load 按原样接受（见 whitespace_submit_load_test.go 的
11	// mustLoadWhitespace），req 也必须与查询、选课、免修使用同一组对象：
12	//   - “s1”与“ s1 ”是两名不同学生，“c1”与“ c1 ”是两门不同课程，
13	//     同一学生名下“r1”与“ r1 ”是两项不同要求；普通空格、制表符、
14	//     全角空格（U+3000）都是编号内容；
15	//   - 给带空白的完整编号登记要求只落在编号完全一致的学生名下、指向
16	//     编号完全一致的课程，三个编号原文都保留；另一名学生的要求、
17	//     修读与学分保持原样；
18	//   - 完整学生编号或完整课程编号找不到时明确报对应对象不存在；即使
19	//     去掉空白能碰上另一条记录，也绝不借用那份记录，更不自动创建
20	//     学生或课程；
21	//   - 空字符串编号仍拒绝；要求编号只由空白字符组成时不得建立；
22	//   - 准确命中后沿用现有规则：同一学生名下不同空白写法的同号要求必须
23	//     指向不同课程；同一学生不能换编号为同一课程再建要求；完整三元组
24	//     相同幂等返回原记录；同一完整要求编号改指另一课程整次拒绝；
25	//   - 课程停开不改变建立要求的规则：停开课程仍可登记要求，新要求本身
26	//     不带来学分。
27	
28	// reqWhitespaceData 构造一份“同号带空白”对象并存的合法记录：
29	// 学生 "s1" 与 " s1 "、课程 "c1" 与 " c1 "（名称、学分各不相同），
30	// "s1" 名下有要求 r1 指向 "c1"，" s1 " 名下有要求 r1 指向 " c1 "。
31	func reqWhitespaceData() *fileData {
32		return &fileData{
33			Version: recordVersion,
34			Courses: []*Course{
35				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
36				{ID: " c1 ", Name: "全角物理", Credit: 3, Open: true},
37			},
38			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
39			Requirements: []*Requirement{
40				{ID: "r1", StudentID: "s1", CourseID: "c1"},
41				{ID: "r1", StudentID: " s1 ", CourseID: " c1 "},
42			},
43		}
44	}
45	
46	// TestAddRequirementWhitespaceStudentIDExact 为 " s1 " 登记新要求时，
47	// 只在 " s1 " 名下保存这一份要求并保留完整学生编号；"s1" 的要求保持
48	// 原样。课程用 "s1" 的 r1 已引用的 "c1"：重复课程限制按学生隔离，
49	// " s1 " 仍可就该课程建立要求。
50	func TestAddRequirementWhitespaceStudentIDExact(t *testing.T) {
51		s, _ := mustLoadWhitespace(t, reqWhitespaceData())
52	
53		r, action, err := s.AddRequirement(" s1 ", "r2", "c1")
54		if err != nil || action != ActionCreated {
55			t.Fatalf("给 \" s1 \" 登记 r2 应成功，action=%v err=%v", action, err)
56		}
57		if r.StudentID != " s1 " || r.ID != "r2" || r.CourseID != "c1" {
58			t.Fatalf("新要求应登记在完整编号学生名下，得到 %+v", r)
59		}
60	
61		// " s1 " 名下有 r1、r2 两份要求；"s1" 名下仍只有 r1，没有被误登记。
62		if got := s.Requirements(" s1 "); len(got) != 2 {
63			t.Fatalf("\" s1 \" 应有两份要求，得到 %+v", got)
64		}
65		if got := s.Requirements("s1"); len(got) != 1 || got[0].ID != "r1" {
66			t.Fatalf("\"s1\" 的要求不应变化，得到 %+v", got)
67		}
68		if s.Requirement("s1", "r2") != nil {
69			t.Fatal("r2 不应登记到 \"s1\" 名下")
70		}
71	}
72	
73	// TestAddRequirementWhitespaceAllIDsPreserved 题目主场景：记录中同时有
74	// "s1" 与 " s1 " 两名学生、"c1" 与 " c1 " 两门课程，为 " s1 " 登记
75	// 指向 " c1 " 的要求 " r1 "，只在该学生名下保存这一份要求，三个编号
76	// 原文全部保留；另一名学生的要求与学分保持原样。
77	func TestAddRequirementWhitespaceAllIDsPreserved(t *testing.T) {
78		d := &fileData{
79			Version: recordVersion,
80			Courses: []*Course{
81				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
82				{ID: " c1 ", Name: "大学物理", Credit: 3, Open: true},
83			},
84			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
85			Requirements: []*Requirement{
86				{ID: "r1", StudentID: "s1", CourseID: "c1"},
87			},
88		}
89		s, _ := mustLoadWhitespace(t, d)
90	
91		r, action, err := s.AddRequirement(" s1 ", " r1 ", " c1 ")
92		if err != nil || action != ActionCreated {
93			t.Fatalf("为 \" s1 \" 登记 \" r1 \" -> \" c1 \" 应成功，action=%v err=%v", action, err)
94		}
95		if r.StudentID != " s1 " || r.ID != " r1 " || r.CourseID != " c1 " {
96			t.Fatalf("三个编号原文都应保留，得到 %+v", r)
97		}
98	
99		// 只在 " s1 " 名下新增这一份要求。
100		got := s.Requirement(" s1 ", " r1 ")
101		if got == nil || got.CourseID != " c1 " {
102			t.Fatalf("\" s1 \" 名下应能按完整编号查到新要求，得到 %+v", got)
103		}
104		if s.Requirement("s1", " r1 ") != nil {
105			t.Fatal("带空白的要求编号不应出现在 \"s1\" 名下")
106		}
107		if s.Requirement(" s1 ", "r1") != nil {
108			t.Fatal("不应把去空白后的 \"r1\" 也登记到 \" s1 \" 名下")
109		}
110		if all := s.AllRequirements(); len(all) != 2 {
111			t.Fatalf("整份记录应仍只有两份要求，得到 %+v", all)
112		}
113	
114		// 另一名学生的要求与课程指向保持原样。
115		orig := s.Requirement("s1", "r1")
116		if orig == nil || orig.CourseID != "c1" {
117			t.Fatalf("\"s1\" 的 r1 应仍指向 \"c1\"，得到 %+v", orig)
118		}
119	}
120	
121	// TestAddRequirementWhitespaceReqIDDistinctButCourseGuard 同一学生名下
122	// "r1" 与 " r1 " 是两项不同要求，可以并存，但仍须指向不同课程；指向
123	// 同一门课程时按“同学生同课程不得重复建立”拒绝。
124	func TestAddRequirementWhitespaceReqIDDistinctButCourseGuard(t *testing.T) {
125		d := &fileData{
126			Version: recordVersion,
127			Courses: []*Course{
128				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
129				{ID: "c2", Name: "大学物理", Credit: 3, Open: true},
130			},
131			Students: []*Student{{ID: "s1"}},
132			Requirements: []*Requirement{
133				{ID: "r1", StudentID: "s1", CourseID: "c1"},
134			},
135		}
136		s, _ := mustLoadWhitespace(t, d)
137	
138		// " r1 " 是另一项要求，指向不同课程 c2：允许新建。
139		r, action, err := s.AddRequirement("s1", " r1 ", "c2")
140		if err != nil || action != ActionCreated {
141			t.Fatalf("同号不同空白的要求指向不同课程应允许，action=%v err=%v", action, err)
142		}
143		if r.ID != " r1 " || r.CourseID != "c2" {
144			t.Fatalf("新要求应保留完整编号并指向 c2，得到 %+v", r)
145		}
146		if got := s.Requirement("s1", "r1"); got == nil || got.CourseID != "c1" {
147			t.Fatalf("原要求 r1 -> c1 不应变化，得到 %+v", got)
148		}
149	
150		// 再用第三个写法的编号指向 c1：同一学生就同一课程换编号仍拒绝。
151		if _, _, err := s.AddRequirement("s1", "r2", "c1"); err == nil ||
152			!strings.Contains(err.Error(), "重复建立") {
153			t.Fatalf("同一学生就同一课程换编号再建应拒绝，得到 %v", err)
154		}
155		// " r1 " 也不能再指向 c1（c1 已被 r1 引用）。
156		if _, _, err := s.AddRequirement("s1", " r1 ", "c1"); err == nil {
157			t.Fatal("同一完整要求编号改指另一门课程应拒绝")
158		}
159		if got := s.Requirement("s1", " r1 "); got.CourseID != "c2" {
160			t.Fatalf("拒绝改指后 \" r1 \" 应保留原指向 c2，得到 %+v", got)
161		}
162		if got := s.Requirements("s1"); len(got) != 2 {
163			t.Fatalf("拒绝后仍应只有 r1、 r1 两份要求，得到 %+v", got)
164		}
165	}
166	
167	// TestAddRequirementWhitespaceIdempotentExact 完整学生编号、要求编号与
168	// 课程编号均与已有要求相同时返回原记录，不新增要求、不标记变更。
169	func TestAddRequirementWhitespaceIdempotentExact(t *testing.T) {
170		s, _ := mustLoadWhitespace(t, reqWhitespaceData())
171		s.dirty = false
172	
173		existing := s.Requirement(" s1 ", "r1")
174		got, action, err := s.AddRequirement(" s1 ", "r1", " c1 ")
175		if err != nil || action != ActionExisted || got != existing {
176			t.Fatalf("完整三元组相同应幂等返回原记录，action=%v err=%v got=%+v", action, err, got)
177		}
178		if s.Dirty() {
179			t.Fatal("幂等返回不应标记变更")
180		}
181	
182		// 仅课程编号的空白不同就是另一门课程：不得当成幂等命中，而应按
183		// “同号要求改指课程”拒绝（"c1" 这门课存在）。
184		if _, _, err := s.AddRequirement(" s1 ", "r1", "c1"); err == nil ||
185			!strings.Contains(err.Error(), "不能改指") {
186			t.Fatalf("完整编号不同的课程应视为改指并拒绝，得到 %v", err)
187		}
188		if c := s.Requirement(" s1 ", "r1").CourseID; c != " c1 " {
189			t.Fatalf("原指向 \" c1 \" 应保留，得到 %q", c)
190		}
191	}
192	
193	// TestAddRequirementWhitespaceNoBorrow 完整编号找不到时必须明确拒绝：
194	// 即使去掉空白能碰上另一名学生或另一门课程，也绝不借用、不自动创建；
195	// 空字符串编号仍拒绝；要求编号全部由空白字符组成时拒绝。所有拒绝都
196	// 不产生变更。
197	func TestAddRequirementWhitespaceNoBorrow(t *testing.T) {
198		// 学生不存在场景：记录里只有 "s1"。
199		dStudent := &fileData{
200			Version: recordVersion,
201			Courses: []*Course{
202				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
203			},
204			Students:     []*Student{{ID: "s1"}},
205			Requirements: nil,
206		}
207		for _, student := range []string{" s1", "s1 ", " s1 ", "\ts1\t", "　s1　"} {
208			s, _ := mustLoadWhitespace(t, dStudent)
209			_, _, err := s.AddRequirement(student, "r1", "c1")
210			if err == nil || !strings.Contains(err.Error(), "不存在") ||
211				!strings.Contains(err.Error(), "学生") {
212				t.Fatalf("学生 %q 不存在，登记应明确拒绝，得到 %v", student, err)
213			}
214			if got := s.Requirement(student, "r1"); got != nil {
215				t.Fatalf("不应自动创建学生 %q 并登记要求", student)
216			}
217			if s.Dirty() {
218				t.Fatalf("被拒绝的登记不应产生变更（学生 %q）", student)
219			}
220		}
221	
222		// 课程不存在场景：记录里只有 "c1"；学生用 "s1" 与 " s1 " 两名，
223		// 验证带空白的课程编号不会借用去空白后的课程。
224		dCourse := &fileData{
225			Version: recordVersion,
226			Courses: []*Course{
227				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
228			},
229			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
230		}
231		for _, course := range []string{" c1", "c1 ", " c1 ", "\tc1\t", "　c1　"} {
232			s, _ := mustLoadWhitespace(t, dCourse)
233			_, _, err := s.AddRequirement(" s1 ", "r1", course)
234			if err == nil || !strings.Contains(err.Error(), "不存在") ||
235				!strings.Contains(err.Error(), "课程") {
236				t.Fatalf("课程 %q 不存在，登记应明确拒绝，得到 %v", course, err)
237			}
238			if got := s.Requirements(" s1 "); len(got) != 0 {
239				t.Fatalf("课程 %q 被拒绝后不应新增要求，得到 %+v", course, got)
240			}
241			if s.Course(course) != nil {
242				t.Fatalf("不应自动创建课程 %q", course)
243			}
244			if s.Dirty() {
245				t.Fatalf("被拒绝的登记不应产生变更（课程 %q）", course)
246			}
247		}
248	
249		// 空字符串编号仍拒绝。
250		s, _ := mustLoadWhitespace(t, dCourse)
251		for _, args := range [3][3]string{
252			{"", "r1", "c1"},
253			{"s1", "", "c1"},
254			{"s1", "r1", ""},
255		} {
256			if _, _, err := s.AddRequirement(args[0], args[1], args[2]); err == nil {
257				t.Fatalf("空字符串编号应被拒绝：%v", args)
258			}
259		}
260	
261		// 要求编号全部由空白字符组成时拒绝：普通空格、制表符、全角空格一样。
262		for _, reqID := range []string{" ", "  ", "\t", "　"} {
263			if _, _, err := s.AddRequirement("s1", reqID, "c1"); err == nil ||
264				!strings.Contains(err.Error(), "要求编号") {
265				t.Fatalf("只含空白的要求编号 %q 应被明确拒绝，得到 %v", reqID, err)
266			}
267			if got := s.Requirement("s1", reqID); got != nil {
268				t.Fatalf("不应建立编号 %q 的要求，得到 %+v", reqID, got)
269			}
270		}
271		if got := s.AllRequirements(); len(got) != 0 {
272			t.Fatalf("全部拒绝后不应有任何要求，得到 %+v", got)
273		}
274		if s.Dirty() {
275			t.Fatal("全部被拒绝的登记不应产生变更")
276		}
277	}
278	
279	// TestAddRequirementWhitespaceClosedCourseAllowed 课程是否停开不改变
280	// 建立要求的既有规则：停开课程仍可登记新要求，新要求初始未满足、不
281	// 带来学分，之后只有修读通过或有效免修才能满足。
282	func TestAddRequirementWhitespaceClosedCourseAllowed(t *testing.T) {
283		d := &fileData{
284			Version: recordVersion,
285			Courses: []*Course{
286				{ID: " c1 ", Name: "大学物理", Credit: 3, Open: false},
287			},
288			Students: []*Student{{ID: " s1 "}},
289		}
290		s, _ := mustLoadWhitespace(t, d)
291	
292		r, action, err := s.AddRequirement(" s1 ", " r1 ", " c1 ")
293		if err != nil || action != ActionCreated {
294			t.Fatalf("停开课程仍应允许登记要求，action=%v err=%v", action, err)
295		}
296		if r.CourseID != " c1 " || r.ID != " r1 " {
297			t.Fatalf("应保留完整编号，得到 %+v", r)
298		}
299		// 新要求本身不带来学分、未满足。
300		rep := s.CheckStudent(" s1 ")
301		if !rep.Found || rep.TotalCredits != 0 || len(rep.Unmet) != 1 || rep.Unmet[0] != " r1 " {
302			t.Fatalf("新要求应未满足且不计学分，得到 %+v", rep)
303		}
304	}
