223			// 要求编号全部由空白字符组成时拒绝。
224			{"要求编号全空格", dStudent, []string{"req", "s1", "  ", "c1"}, []string{"要求编号"}},
225			{"要求编号制表符", dStudent, []string{"req", "s1", "\t", "c1"}, []string{"要求编号"}},
226			{"要求编号全角空格", dStudent, []string{"req", "s1", "　", "c1"}, []string{"要求编号"}},
227		}
228		for _, tc := range cases {
229			t.Run(tc.label, func(t *testing.T) {
230				file, raw := writeDiskRecord(t, tc.d)
231				out, errText, code := runCLI(t, file, tc.args...)
232				if code != exitRejected {
233					t.Fatalf("%s：应业务拒绝（退出码 1），code=%d out=%q err=%q",
234						tc.label, code, out, errText)
235				}
236				if strings.Contains(out, "已为学生") || strings.Contains(out, "返回原记录") {
237					t.Fatalf("%s：被拒绝时 stdout 不应有登记成功或返回原要求的提示，out=%q",
238						tc.label, out)
239				}
240				for _, want := range tc.wantErr {
241					if !strings.Contains(errText, want) {
242						t.Fatalf("%s：错误输出应包含 %q，err=%q", tc.label, want, errText)
243					}
244				}
245				assertFileByteIdentical(t, file, raw, tc.label+"：")
246			})
247		}
248	}
249	
250	// TestCLIReqWhitespaceExistingRecordsUntouched 已有带空白编号的合法
251	// 记录继续可读：被拒绝的登记不能改写、合并或重新解释其中的要求，冲突
252	// 前后记录文件逐字节一致。
253	func TestCLIReqWhitespaceExistingRecordsUntouched(t *testing.T) {
254		file, _ := writeDiskRecord(t, reqWhitespaceCLIRecord())
255	
256		// 先在 " s1 " 名下建立 " r1 " -> " c1 "。
257		if _, _, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 "); code != 0 {
258			t.Fatal("首次登记应成功")
259		}
260	
261		// 同一完整要求编号改指另一门课程：整次拒绝，文件逐字节保持原样。
262		before := mustReadRecord(t, file)
263		out, errText, code := runCLI(t, file, "req", " s1 ", " r1 ", "c1")
264		if code != exitRejected || !strings.Contains(errText, "不能改指") {
265			t.Fatalf("改指应拒绝，code=%d out=%q err=%q", code, out, errText)
266		}
267		if strings.Contains(out, "已为学生") || strings.Contains(out, "返回原记录") {
268			t.Fatalf("被拒绝时 stdout 不应有登记成功或返回原要求的提示，out=%q", out)
269		}
270		assertRecordUnchanged(t, file, before, "改指拒绝：")
271	
272		// 重新打开记录：带空白的编号原文（" s1 "、" r1 "、" c1 "）仍在，
273		// 没有被修剪或合并；"s1" 的 r1 -> c1 也保持原样。
274		out, _, code = runCLI(t, file, "show", " s1 ")
275		if code != 0 || !strings.Contains(out, "要求  r1  -> 课程  c1 《大学物理》3 学分") {
276			t.Fatalf("已有带空白编号的记录应原样保留，code=%d out=%q", code, out)
277		}
278		out, _, _ = runCLI(t, file, "show", "s1")
279		if !strings.Contains(out, "要求 r1 -> 课程 c1《高等数学》4 学分") {
280			t.Fatalf("\"s1\" 的原要求应保持，out=%q", out)
281		}
282	}
283	
284	// TestCLIReqWhitespaceClosedCourseAllowed 课程停开不改变建立要求的
285	// 规则：停开课程仍可登记要求，新要求不带来学分，show 仍显示课程名称
286	// 与学分；只是之后不能在该要求上新增修读。
287	func TestCLIReqWhitespaceClosedCourseAllowed(t *testing.T) {
288		d := &diskRecord{
289			Version: 1,
290			Courses: []diskCourse{
291				{ID: " c1 ", Name: "大学物理", Credit: 3, Open: false},
292			},
293			Students: []diskStudent{{ID: " s1 "}},
294		}
295		file, _ := writeDiskRecord(t, d)
296	
297		out, errText, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 ")
298		if code != 0 || !strings.Contains(out, "已为学生  s1  登记要求  r1 ，指向课程  c1 ") {
299			t.Fatalf("停开课程仍应允许登记要求，code=%d out=%q err=%q", code, out, errText)
300		}
301	
302		// 新要求本身不带来学分、未满足。
303		out, _, code = runCLI(t, file, "check", " s1 ")
304		if code != 0 || !strings.Contains(out, "总学分：0") ||
305			!strings.Contains(out, "未满足要求：[ r1 ]") {
306			t.Fatalf("新要求应未满足且不计学分，code=%d out=%q", code, out)
307		}
308		// show 仍按课程记录显示名称与学分（停开只是不能新增修读）。
309		out, _, _ = runCLI(t, file, "show", " s1 ")
310		if !strings.Contains(out, "要求  r1  -> 课程  c1 《大学物理》3 学分") {
311			t.Fatalf("show 应显示实际指向课程的名称与学分，out=%q", out)
312		}
313		// 后续满足途径仍按既有规则：停开课程不能新增修读。
314		out, errText, code = runCLI(t, file, "enroll", " s1 ", " r1 ", "2024春", "e1")
315		if code != exitRejected || !strings.Contains(errText, "停开") {
316			t.Fatalf("停开课程应不能新增修读，code=%d out=%q err=%q", code, out, errText)
317		}
318	}
