844		if !st.Satisfied || st.Source != "waiver" || st.WaiverID != "w1" {
845			t.Fatalf("免修有效时应以免修 w1 说明来源，得到 %+v", st)
846		}
847		if len(st.PassedEnrollmentIDs) != 2 ||
848			st.PassedEnrollmentIDs[0] != "e2" || st.PassedEnrollmentIDs[1] != "e1" {
849			t.Fatalf("两次通过应按提交先后保留在修读历史中，得到 %v", st.PassedEnrollmentIDs)
850		}
851		if len(rep.Unmet) != 0 {
852			t.Fatalf("免修有效时不应有未满足要求，得到 %v", rep.Unmet)
853		}
854	
855		// 撤销免修并填写原因。
856		w, changed, err := s.RevokeWaiver("s1", "w1", "获奖材料无法核实")
857		if err != nil || !changed || w.Status != WaiverRevoked {
858			t.Fatalf("撤销有效免修应成功，changed=%v 得到 %+v err=%v", changed, w, err)
859		}
860	
861		// 撤销后：要求继续满足、总学分不变，来源改回最先提交通过的 e2。
862		rep = s.CheckStudent("s1")
863		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
864			t.Fatalf("撤销后要求应继续满足、总学分不变，得到学分=%d 未满足=%v",
865				rep.TotalCredits, rep.Unmet)
866		}
867		st = rep.Requirements[0]
868		if !st.Satisfied || st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
869			t.Fatalf("撤销后来源应改回最先提交通过的 e2，得到 %+v", st)
870		}
871		if len(st.PassedEnrollmentIDs) != 2 ||
872			st.PassedEnrollmentIDs[0] != "e2" || st.PassedEnrollmentIDs[1] != "e1" {
873			t.Fatalf("撤销后修读历史不应丢失，得到 %v", st.PassedEnrollmentIDs)
874		}
875		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w1" {
876			t.Fatalf("核对应列出已撤销免修 w1，得到 %v", rep.RevokedWaivers)
877		}
878	
879		// 通过修读的结果与提交先后保持原样；免修历史完整保留。
880		assertTwoPassesIntact(t, s)
881		assertRevokedWaiverKept(t, s, "获奖材料无法核实")
882	
883		// 保存并重新打开：恢复的学分来源与免修历史仍然可查。
884		path := filepath.Join(t.TempDir(), "records.json")
885		if err := s.Save(path); err != nil {
886			t.Fatalf("Save: %v", err)
887		}
888		loaded, existed, err := Load(path)
889		if err != nil || !existed {
890			t.Fatalf("Load: existed=%v err=%v", existed, err)
891		}
892		rep = loaded.CheckStudent("s1")
