914		mustReq(t, s, "s1", "r1", "c1")
915		mustReq(t, s, "s1", "r2", "c2")
916	
917		// r1 只有一次选课和一次未通过，没有任何通过记录。
918		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
919		mustEnroll(t, s, "s1", "r1", "2024春", "e2")
920		if _, _, err := s.SubmitResult("s1", "e2", Failed); err != nil {
921			t.Fatal(err)
922		}
923		// r2 是另一项已通过的要求，用于验证不受撤销影响。
924		mustEnroll(t, s, "s1", "r2", "2024春", "e3")
925		if _, _, err := s.SubmitResult("s1", "e3", Passed); err != nil {
926			t.Fatal(err)
927		}
928	
929		// 免修有效期间：r1 由免修满足，总学分含免修提供的 4 学分。
930		if _, _, err := s.ApplyWaiver("s1", "r1", "w1", "外校同层次课程"); err != nil {
931			t.Fatal(err)
932		}
933		rep := s.CheckStudent("s1")
934		if rep.TotalCredits != 7 || len(rep.Unmet) != 0 {
935			t.Fatalf("免修有效时总学分应为 7 且无未满足，得到学分=%d 未满足=%v",
936				rep.TotalCredits, rep.Unmet)
937		}
938		if st := rep.Requirements[0]; st.Source != "waiver" || st.WaiverID != "w1" {
939			t.Fatalf("r1 应由有效免修 w1 满足，得到 %+v", st)
940		}
941	
942		// 撤销免修。
943		if _, changed, err := s.RevokeWaiver("s1", "w1", "材料无法核实"); err != nil || !changed {
944			t.Fatalf("撤销应成功，changed=%v err=%v", changed, err)
945		}
946	
947		// 撤销后：r1 回到未满足，总学分失去免修提供的 4 学分。
948		rep = s.CheckStudent("s1")
949		if rep.TotalCredits != 3 {
950			t.Fatalf("撤销后应只剩 r2 的 3 学分，得到 %d", rep.TotalCredits)
951		}
952		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
953			t.Fatalf("r1 应回到未满足，得到 %v", rep.Unmet)
954		}
955		st := rep.Requirements[0]
956		if st.Satisfied || st.Source != "" || st.WaiverID != "" || st.PassedEnrollmentID != "" {
957			t.Fatalf("已撤销免修与未通过修读都不能作为来源，得到 %+v", st)
958		}
959		if len(st.PassedEnrollmentIDs) != 0 {
960			t.Fatalf("没有通过记录，通过历史应为空，得到 %v", st.PassedEnrollmentIDs)
961		}
962	
963		// 已有选课与未通过记录仍然可查、结果不变。
964		if e := s.Enrollment("s1", "e1"); e == nil || e.Result != Enrolled {
965			t.Fatalf("选课记录 e1 应保留为选课，得到 %+v", e)
966		}
967		if e := s.Enrollment("s1", "e2"); e == nil || e.Result != Failed {
968			t.Fatalf("未通过记录 e2 应保留为未通过，得到 %+v", e)
969		}
970	
971		// 免修历史保留撤销状态与原因。
972		w := s.Waiver("s1", "w1")
973		if w == nil || w.Status != WaiverRevoked || w.Basis != "外校同层次课程" ||
974			w.Reason != "材料无法核实" || w.ReqID != "r1" {
975			t.Fatalf("免修历史应保留原依据与撤销原因，得到 %+v", w)
976		}
977		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w1" {
978			t.Fatalf("核对应列出已撤销免修 w1，得到 %v", rep.RevokedWaivers)
979		}
980	
981		// 其他要求 r2 的满足情况与学分不受这次撤销影响。
982		other := rep.Requirements[1]
983		if !other.Satisfied || other.Source != "enrollment" || other.PassedEnrollmentID != "e3" {
984			t.Fatalf("r2 应继续由通过修读 e3 满足，得到 %+v", other)
985		}
986		if e := s.Enrollment("s1", "e3"); e == nil || e.Result != Passed {
987			t.Fatalf("r2 的通过记录不应改变，得到 %+v", e)
988		}
989	}
990	
991	// TestRevokeRevokedWaiverKeepsFirstReasonAndSource 同一份已撤销免修再次
992	// 被撤销时返回原结果：后来给出的不同原因不能覆盖首次撤销原因，也不能
993	// 改变已经恢复的学分来源。
994	func TestRevokeRevokedWaiverKeepsFirstReasonAndSource(t *testing.T) {
995		s := NewStore()
996		setupTwoPassesAndWaiver(t, s)
997	
998		if _, changed, err := s.RevokeWaiver("s1", "w1", "首次撤销：材料存疑"); err != nil || !changed {
999			t.Fatalf("首次撤销应成功，changed=%v err=%v", changed, err)
1000		}
1001		// 撤销后来源已恢复为最先提交通过的 e2。
1002		rep := s.CheckStudent("s1")
1003		if st := rep.Requirements[0]; st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
1004			t.Fatalf("首次撤销后来源应恢复为 e2，得到 %+v", st)
1005		}
1006	
1007		// 用不同原因再次撤销：返回原结果，原因与来源都不变。
1008		for _, reason := range []string{"第二次填写的原因", ""} {
1009			w, changed, err := s.RevokeWaiver("s1", "w1", reason)
1010			if err != nil || changed {
1011				t.Fatalf("重复撤销应幂等返回原结果，changed=%v err=%v", changed, err)
1012			}
1013			if w.Status != WaiverRevoked || w.Reason != "首次撤销：材料存疑" {
1014				t.Fatalf("首次撤销原因不应被覆盖，得到 %+v", w)
1015			}
1016		}
1017		if n := len(s.Waivers("s1")); n != 1 {
1018			t.Fatalf("重复撤销不应新增免修记录，得到 %d 条", n)
1019		}
1020	
1021		// 学分来源与修读历史保持首次撤销后恢复的结果。
1022		rep = s.CheckStudent("s1")
1023		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
1024			t.Fatalf("重复撤销不应改变学分，得到学分=%d 未满足=%v", rep.TotalCredits, rep.Unmet)
1025		}
1026		st := rep.Requirements[0]
1027		if st.Source != "enrollment" || st.PassedEnrollmentID != "e2" ||
1028			len(st.PassedEnrollmentIDs) != 2 {
1029			t.Fatalf("重复撤销不应改变已恢复的来源 e2，得到 %+v", st)
1030		}
1031		if len(rep.RevokedWaivers) != 1 || rep.RevokedWaivers[0] != "w1" {
1032			t.Fatalf("已撤销免修列表应保持 [w1]，得到 %v", rep.RevokedWaivers)
1033		}
1034		assertTwoPassesIntact(t, s)
1035		assertRevokedWaiverKept(t, s, "首次撤销：材料存疑")
1036	}
