		t.Fatalf("未被引用的 \" c1 \" 应允许更新，action=%v err=%v", a, err)
	}
	if _, _, err := s2.AddCourse("c1", "高等数学（下）", 6); err == nil {
		t.Fatal("被引用的 \"c1\" 改学分应拒绝")
	}
	if c := s2.Course("c1"); c.Name != "高等数学" || c.Credit != 4 {
