// 允许按现有规则更新，但停开状态必须保持，不能借重新登记恢复开放。
func TestAddCourseWhitespaceClosedStaysClosed(t *testing.T) {
	d := &fileData{
		Version: recordVersion,
		Courses: []*Course{
			{ID: " c1 ", Name: "大学物理", Credit: 3, Open: false},
